// pnpm seed:build — regenerate supabase/seed.sql from every tenants/<slug>/business.json.
// The seed goes through the same private.apply_business_config() as tenant:publish.
import fs from 'node:fs';
import path from 'node:path';
import { toDbPayload } from '../shared/business-schema.ts';
import { ROOT, listTenantSlugs, loadTenant, printReport } from './lib/tenants.ts';

const parts = [
  '-- GENERATED by `pnpm seed:build` from tenants/*/business.json. Do not edit by hand.',
  '-- Demo studios start in preview; bookings below are flagged is_demo.',
  '',
];
for (const slug of listTenantSlugs()) {
  const r = await loadTenant(slug);
  if (!r.business) {
    printReport(r);
    process.exit(1);
  }
  const json = JSON.stringify(toDbPayload(r.business));
  if (json.includes('$cfg$')) throw new Error('config contains reserved $cfg$ marker');
  parts.push(`-- ${slug}`);
  parts.push(`select private.apply_business_config($cfg$${json}$cfg$::jsonb);`);
  parts.push(
    `select private.seed_demo_bookings((select id from public.tenants where slug = '${slug}'), ${r.business.demo.bookings});`,
  );
  parts.push('');
}
const out = path.join(ROOT, 'supabase', 'seed.sql');
fs.writeFileSync(out, parts.join('\n'));
console.log(`seed.sql: ${listTenantSlugs().length} студий`);
